const orders = $('Get Orders').all()
  .map(o => o.json)
  .filter(o => ['Confirmed', 'Preparing', 'Out for Delivery'].includes(o.status));

const customers = $input.all().map(c => c.json);

if (orders.length === 0) {
  return [{ json: { text: "📋 No active orders right now." } }];
}

const lines = orders.map(o => {
  const customer = customers.find(c => c.id === o.customer_id);
  const name = customer ? customer.name : "Unknown";
  return `#${o.order_number} — ${name} — Rs. ${o.total_amount} — ${o.status}`;
});

return [{ json: { text: "📋 Active Orders\n" + lines.join("\n") } }];

// Replies about the order are built from what the tools REALLY returned. The model sometimes ignores tool results.
let forced = null;
try {
  const steps = Array.isArray($json.intermediateSteps) ? $json.intermediateSteps : [];
  const toolOf = s => String(s?.action?.tool || '');
  const obsOf = s => {
    let o = s?.observation;
    if (typeof o === 'string') { try { o = JSON.parse(o); } catch (e) { o = null; } }
    if (Array.isArray(o)) o = o[0];
    return (o && typeof o === 'object') ? o : null;
  };
  const isAdd = s => /add.?order.?item/i.test(toolOf(s));
  const isSummary = s => /get.?order.?summary/i.test(toolOf(s));
  const isFinal = s => /finalize.?order/i.test(toolOf(s));
  const last = steps.length ? steps[steps.length - 1] : null;
  const modelText = String($json.output || '');

  if (last && (isSummary(last) || isFinal(last)) && obsOf(last)?.reply_text) {
    // 1) order summary or final confirmation: send the tool's own text
    forced = obsOf(last).reply_text;
  } else if ((last && isAdd(last)) || /added\s+\d+\s*x/i.test(modelText)) {
    // 2) items added this turn (only steps after the most recent Create Order)
    let from = 0;
    steps.forEach((s, i) => { if (/create.?order/i.test(toolOf(s))) from = i + 1; });
    const addSteps = steps.slice(from).filter(isAdd);
    const ok = [], bad = [], okNames = [];
    for (const s of addSteps) {
      const o = obsOf(s);
      if (o?.reply_text) { ok.push(o.reply_text); okNames.push(String(o.item_name || '').toLowerCase()); }
      else if (o?.customer_message) bad.push(o.customer_message);
    }
    // items the model says it added but no successful Add Order Item backs up
    const claimed = [...modelText.matchAll(/added\s+\d+\s*x\s+(.+?)\s*✅/gi)].map(m => m[1].trim());
    const missing = claimed.filter(n => !okNames.some(k => k && (k.includes(n.toLowerCase()) || n.toLowerCase().includes(k))));
    missing.forEach(n => bad.push(`Sorry 🙏 I couldn't add ${n} yet. Please send it again.`));
    if (ok.length || bad.length) {
      forced = [...ok, ...bad].join('\n') + (bad.length ? '' : "\n\nAnything else you'd like to add? 😊");
    }
  }

  // 3) the model wrote a summary or a confirmation that no tool result backs up: never send it
  if (forced === null) {
    if (/your order is confirmed/i.test(modelText)) {
      forced = 'Sorry 🙏 I could not confirm your order just now. Please reply *YES* again.';
    } else if (/here'?s your order/i.test(modelText)) {
      forced = 'Sorry 🙏 I could not prepare your order summary just now. Please send your last message again.';
    }
  }
} catch (e) {}

let output = String(forced !== null ? forced : ($json.output || '')).replace(/\*\*(.+?)\*\*/g, '*$1*');

// The model sometimes copies the <<<MENU / MENU>>> fence lines; customers must never see them
output = output.replace(/^[ \t]*(?:<<<\s*MENU|MENU\s*>>>)[ \t]*\r?\n?/gim, '').replace(/\n{3,}/g, '\n\n');

// Safety net: fix prices, names and stock notes on numbered menu lines the model typed itself
try {
  const bm = $('Build Menu Text').first().json;
  const shown = new Set((bm.display_lines || []).map(l => l.trim()));
  const menu = [];
  String(bm.menu_text || '')
    .split('\n')
    .map(l => l.split(' | '))
    .filter(p => p.length >= 2)
    .forEach(p => {
      const full = p[0].trim();
      const price = (String(p[1]).match(/\d+(?:\.\d+)?/) || [''])[0];
      const left = (String(p[2] || '').match(/only (\d+) left/) || [])[1];
      if (!full || !price) return;
      menu.push({ full, name: full.toLowerCase(), price, left });
      const short = full.replace(/^deal\s*\d+\s*[-–:]\s*/i, '');
      if (short !== full) menu.push({ full, name: short.toLowerCase(), price, left, alias: true });
    });
  menu.sort((a, b) => b.name.length - a.name.length);
  output = output.split('\n').map(line => {
    if (shown.has(line.trim())) return line; // already the exact ready-made menu line
    if (!/^\s*\d+[.)]\s/.test(line)) return line;
    const low = line.toLowerCase();
    const hit = menu.find(m => low.includes(m.name));
    if (!hit) return line;
    let out = line;
    if (hit.alias && !low.includes(hit.full.toLowerCase())) {
      const i = low.indexOf(hit.name);
      out = out.slice(0, i) + hit.full + out.slice(i + hit.name.length);
    }
    out = out.replace(/(Rs\.?\s*)[\d,]+(\.\d+)?/i, (m, p1) => p1 + hit.price);
    out = out.replace(/(?:[\s,—–-]*available,?)?[\s,—–-]*\(?only \d+ left\)?/gi, '');
    if (hit.left) out = out.replace(/\s+$/, '') + ` (only ${hit.left} left)`;
    return out;
  }).join('\n');
} catch (e) {}

const match = output.match(/\[SEND_IMAGE:(.*?)\]/);

if (match) {
  const imageUrl = match[1];
  const caption = output.replace(match[0], '').trim();
  return [{ json: { hasImage: true, imageUrl, caption } }];
}
return [{ json: { hasImage: false, text: output } }];

const item = $input.item.json;
const msg = item.messages[0];
if (msg.type === 'location' && msg.location) {
  msg.text = { body: `[LOCATION SHARED] latitude: ${msg.location.latitude}, longitude: ${msg.location.longitude}` };
}
return { json: item };

const items = $input.all().map(i => i.json).filter(m => m.id && !m.is_archived);
const status = m => {
  if (!m.is_available) return 'unavailable today';
  if (m.is_limited) return Number(m.stock_qty) > 0 ? `available, only ${m.stock_qty} left` : 'out of stock';
  return 'available';
};
const fmt = m => `${m.name} | Rs. ${Number(m.price)} | ${status(m)}`;
const deals = items.filter(m => m.is_deal).sort((a, b) => (a.deal_number || 0) - (b.deal_number || 0));
const regular = items.filter(m => !m.is_deal);
const until = d => d.valid_until ? new Date(new Date(d.valid_until).getTime() - 60000)
  .toLocaleDateString('en-GB', { timeZone: 'Asia/Karachi', day: 'numeric', month: 'short' }) : '';
const tag = m => {
  if (!m.is_available) return ' ❌ unavailable today';
  if (m.is_limited) return Number(m.stock_qty) > 0 ? ` ⚠️ only ${m.stock_qty} left` : ' ❌ sold out';
  return '';
};

// Sections come from menu_items.category (set by the owner). Known sections keep a fixed order and emoji; new ones are added alphabetically.
const ORDER = ['Burgers', 'Rolls & Sandwiches', 'Fries & Snacks', 'Karahi & Handi', 'Biryani & Rice', 'Bread & Sides', 'Drinks'];
const EMOJI = { 'burgers': '🍔', 'rolls & sandwiches': '🌯', 'fries & snacks': '🍟', 'karahi & handi': '🍖', 'biryani & rice': '🍛', 'bread & sides': '🫓', 'drinks': '🥤' };
const FALLBACK = 'More Items';
const map = new Map();
for (const m of regular) {
  const k = String(m.category || '').trim() || FALLBACK;
  if (!map.has(k)) map.set(k, []);
  map.get(k).push(m);
}
const rank = k => { const i = ORDER.findIndex(c => c.toLowerCase() === k.toLowerCase()); return i >= 0 ? i : k === FALLBACK ? 1000 : 500; };
const keys = [...map.keys()].sort((a, b) => rank(a) - rank(b) || a.localeCompare(b));

// Ready-made WhatsApp menu with ONE continuous numbering (deals first, then categories)
const display = [];
let n = 0;
if (deals.length) {
  display.push('🔥 *DEALS* 🔥');
  for (const d of deals) {
    n++;
    display.push(`${n}. *${d.name}* — Rs. ${Number(d.price)}${tag(d)}`);
    if (d.deal_description) display.push(`   🎁 ${d.deal_description}`);
    if (d.valid_until) display.push(`   ⏳ valid until ${until(d)}`);
  }
}
for (const k of keys) {
  display.push('');
  display.push(`${EMOJI[k.toLowerCase()] || '🍽️'} *${k.toUpperCase()}*`);
  for (const m of map.get(k).sort((a, b) => a.name.localeCompare(b.name))) { n++; display.push(`${n}. ${m.name} — Rs. ${Number(m.price)}${tag(m)}`); }
}
while (display.length && display[0] === '') display.shift();

const base = $('Normalize Location Message').first().json;
const msgText = String(base?.messages?.[0]?.text?.body || '');
// Only hand the model the ready-made menu block when the customer is actually asking for the menu / starting an order.
// A bare number is never a menu request: it answers the assistant's last question.
const wantsMenu = /menu|price|prices|rates?\b|list|what (do you|u) (have|sell|serve)|what.*(available|options)|show|catalog|\border\b/i.test(msgText);

const lines = [];
if (wantsMenu) {
  lines.push('MENU TO SHOW: the customer is asking for the menu or starting an order. Send the block below EXACTLY as written (same numbers, emojis, stars, category headings and line breaks). Only add one short friendly line before it and "Reply with a number or item name to order 😊" after it. The numbers are what customers reply with. A deal is ONE orderable item: when a customer wants a deal, call Add Order Item once with the deal\'s FULL name (e.g. "Deal 1 - Family Feast"), never its included items separately.');
  lines.push('<<<MENU');
  lines.push(...display);
  lines.push('MENU>>>');
} else {
  lines.push('The customer did NOT ask for the menu in this message. Do NOT show or paste the menu. Continue the order or answer their question using the MENU DATA below. A bare number like 1 or 2 is the customer\'s answer to your LAST question or numbered list, never a request for the menu. A deal is ONE orderable item: add it once with its FULL name, never its included items separately.');
}
lines.push('');
lines.push('MENU DATA (use for questions about price, stock or contents; do not paste this part):');
for (const d of deals) {
  lines.push(fmt(d));
  lines.push(`   includes: ${d.deal_description || ''}${d.valid_until ? ` (valid until ${until(d)})` : ''}`);
}
for (const m of regular) lines.push(fmt(m));
return [{ json: { ...base, menu_text: lines.join('\n'), display_lines: display.filter(Boolean) } }];

const r = $input.first().json || {};
const generic = 'Sorry, something went wrong on our side 🙏 Please send your message again in a minute.';
if (!r.found) return [{ json: { text: generic } }];
const lines = (r.items || []).map(i => `${i.qty}x ${i.name} — Rs. ${i.total}`);
const out = ['Your order is confirmed ✅ (Order #' + r.order_number + ')', ...lines];
if (r.fulfillment_type === 'Delivery') {
  if (r.delivery_address) out.push('Delivery to: ' + r.delivery_address);
  out.push('Delivery fee: Rs. ' + r.delivery_fee);
} else {
  out.push('Pickup');
}
out.push('Total: Rs. ' + r.total_amount);
out.push('');
out.push('Sorry for the delay in replying 🙏 Your order went through successfully.');
return [{ json: { text: out.join('\n') } }];

const out = $input.first().json || {};
const text = out.reply_text
  ? out.reply_text
  : 'Sorry 🙏 I could not confirm your order just now. Please reply *YES* again in a minute.';
return [{ json: { text } }];
